def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((oid, opp))

    if not alive:
        return float(min(budget, 20.0))

    strongest_prev = 0.0
    pressure_bid = 0.0
    desperate_count = 0
    rich_count = 0

    for oid, opp in alive:
        prev = opp.get('previous_trace', {})
        prev_bid = 0.0
        if prev and prev.get('bid') is not None:
            prev_bid = float(prev.get('bid', 0.0))
        if prev_bid > strongest_prev:
            strongest_prev = prev_bid

        opp_hp = opp.get('hp', 0)
        opp_budget = opp.get('budget', 0.0)
        opp_nowater = opp.get('no_water_days', 0)
        opp_req = opp.get('water_requirement', WATER_REQ)
        opp_salary = opp.get('daily_salary', DAILY_SALARY)

        score = prev_bid
        if opp_hp <= 2 or opp_nowater >= 1:
            score += opp_salary * 0.35
            desperate_count += 1
        if opp_budget >= opp_salary * 1.5:
            score += opp_salary * 0.15
            rich_count += 1
        if opp_req <= supply:
            score += 2.0
        if score > pressure_bid:
            pressure_bid = score

    can_only_feed_one = supply < WATER_REQ * 2

    if hp <= 2 or no_water >= 1:
        base = max(DAILY_SALARY * 0.95, pressure_bid + 3.0)
    elif can_only_feed_one:
        base = max(DAILY_SALARY * 0.82, pressure_bid + 2.0)
    else:
        base = max(DAILY_SALARY * 0.28, min(DAILY_SALARY * 0.62, pressure_bid * 0.55 + 1.0))

    if strongest_prev > 150:
        if hp > 3 and no_water == 0 and not can_only_feed_one:
            base = min(base, DAILY_SALARY * 0.42)
        else:
            base = max(base, DAILY_SALARY * 0.88)

    if desperate_count >= 2 and can_only_feed_one:
        base = max(base, DAILY_SALARY * 0.92)

    if rich_count == 0 and hp > 3 and no_water == 0 and not can_only_feed_one:
        base = min(base, DAILY_SALARY * 0.38)

    if day >= 8:
        base += 6.0
    if day == 10:
        base += 8.0

    bid = min(float(budget), float(base))
    if bid < 0:
        bid = 0.0
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    hp = int(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    alive = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive.append((opp_id, opp))

    if not alive:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Read yesterday bids to infer pressure.
    prev_bids = []
    for _, opp in alive:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    # Estimate how many water units likely exist; bid aggressiveness increases with tighter supply.
    # supply is float; indices are not used.
    units_possible = int(supply / WATER_REQ)  # e.g., 19/9 -> 2
    tight = (supply <= (MIN_SUPPLY + 1.0)) or (units_possible <= 1)

    # Determine opponent pressure from yesterday.
    pressure = 0.0
    if prev_bids:
        pressure = max(prev_bids)

    # If someone was bidding extremely high yesterday, we should match moderately; otherwise undercut.
    # Also, if my hp is low or I have had no water for several days, I must secure water.
    must_have = (hp <= 2) or (no_water_days >= 2)

    # Base target bid
    if must_have:
        target = DAILY_SALARY * (0.85 if tight else 0.75)
    else:
        # If yesterday pressure was high, raise; if low, lower.
        if pressure >= DAILY_SALARY * 1.6:
            target = DAILY_SALARY * (0.70 if tight else 0.60)
        elif pressure >= DAILY_SALARY * 1.1:
            target = DAILY_SALARY * (0.60 if tight else 0.50)
        else:
            target = DAILY_SALARY * (0.50 if tight else 0.40)

    # Slightly adapt to remaining budget to avoid overspending.
    # If budget is small, cap bid proportionally.
    budget_cap = budget * (0.75 if must_have else 0.55)
    target = min(target, budget_cap)

    # Add a small increment to beat typical aggressive bids when needed.
    if must_have and pressure > 0:
        target = max(target, min(budget, pressure * 0.55 + 10.0))
    elif not must_have and pressure > 0:
        # Underbid relative to max yesterday pressure.
        target = min(target, max(0.0, pressure * 0.45))

    # Final clamp
    if budget <= 0:
        return 0.0
    bid = max(0.0, min(float(budget), float(target)))
    return bid

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    prev_bids = [o['previous_trace']['bid'] for o in alive_opponents if o.get('previous_trace') and o['previous_trace'].get('bid') is not None]
    max_prev = max(prev_bids) if prev_bids else 0

    if my_status['hp'] <= 3:
        return min(my_status['budget'], max(max_prev * 1.1, DAILY_SALARY * 0.9))

    if supply < 18:
        return min(my_status['budget'], max(max_prev * 1.05, DAILY_SALARY * 0.7))

    return min(my_status['budget'], max(max_prev * 0.8, DAILY_SALARY * 0.4))
